$root=dirname(__DIR__,2);$payload=__DIR__.'/files';$backup=$root.'/storage/backups/v30.1.0-'.date('Ymd-His');$messages=[];$error='';
function rr_copy(string $src,string $dst):void{if(is_dir($src)){if(!is_dir($dst)&&!mkdir($dst,0775,true)&&!is_dir($dst))throw new RuntimeException('Klasör oluşturulamadı: '.$dst);foreach(scandir($src)?:[] as $f){if($f==='.'||$f==='..')continue;rr_copy($src.'/'.$f,$dst.'/'.$f);}}else{if(!is_dir(dirname($dst))&&!mkdir(dirname($dst),0775,true)&&!is_dir(dirname($dst)))throw new RuntimeException('Klasör oluşturulamadı.');if(!copy($src,$dst))throw new RuntimeException('Dosya kopyalanamadı: '.$dst);}}
if($_SERVER['REQUEST_METHOD']==='POST')try{foreach(['staff/index.php','cashier/index.php','app/assets/pos-v5-alpha.css','app/assets/pos-v5-alpha.js'] as $rel){$old=$root.'/'.$rel;if(is_file($old))rr_copy($old,$backup.'/'.$rel);rr_copy($payload.'/'.$rel,$old);$messages[]='Güncellendi: '.$rel;}if(function_exists('opcache_reset'))@opcache_reset();file_put_contents($root.'/storage/update.lock',json_encode(['version'=>'30.1.0-alpha','installed_at'=>date('c')],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$messages[]='POS 5.0 Alpha başarıyla kuruldu.';}catch(Throwable $e){$error=$e->getMessage();}
